func (g *PLEGPU) Format() QuantSim { return g.sim }

// NewPLEGPU stages one layer's n-gram block onto the device.
func NewPLEGPU(dev *vk.Device, cfg PLEConfig, maxTokens int, w PLEWeights, opts PLEOpts) (*PLEGPU, error) {
	if maxTokens <= 0 {
