package main

// P5a — the draft head as a passive observer (LLM.md P5,
// research/p5-mtp-rollback.md).
//
//	go run ./cmd/llm -mtp -mtp-n 256 -mtp-depth 4
//	go run ./cmd/llm -mtp -mtp-n 256 -mtp-free      # the model's own text
//	go run ./cmd/llm -mtp -mtp-n 256 -mtp-control   # the negative control
//
// **The number this exists for is the acceptance rate, and it needs none of
// P5's machinery.** A speculative loop wants to know how often the draft
// head's guess equals the token the trunk would have emitted anyway — and
// that can be watched from the side of an ordinary one-token-at-a-time
// decode, with no rollback, no verification pass and no new kernel:
//
//	at step i the trunk consumes x_i and its logits name y_{i+1} = argmax
//	the draft is handed (h_i, x_{i+1}) at position i+1 and names x̂_{i+2}
//	at step i+1 the trunk names y_{i+2}, and the two are compared
//
// Two modes, because they measure different things and the honest answer is
// both. **teacher-forced** (the default) advances on the corpus's own tokens,
// so the context stays on-distribution and the comparison is still against
// the trunk's argmax — this is the conservative reading. **free-running**
// advances on the trunk's argmax, which is exactly what a speculative loop
// would see, and is the optimistic one because a model's own greedy output is
// more predictable than real text.
//
// **And a negative control, because the wiring is a hypothesis.** There is no
// reference implementation of this architecture's MTP block anywhere (see
// llm/mtp.go), so a plausible-looking acceptance rate has to be shown to
// depend on the trunk's hidden state at all: `-mtp-control` hands the draft a
// **zeroed** residual, leaving it nothing but the token embedding. If the
// rate survives that, the head is doing bigram prediction and the wiring is
// unproven whatever the first number said.

import (
	"fmt"
	"os"
	"time"

	"strix-halo-vulkan/llm"
)

type mtpOpts struct {
	model, draft string
	file, prompt string
	n, ctx       int
	layers       int
	depth        int
	free         bool
	control      bool
	csv          string
}

// mtpObserve stages the trunk and the draft head and walks a sequence one
// token at a time, counting agreements.
func mtpObserve(o mtpOpts) error {
	m, err := llm.Open(o.model)
	if err != nil {
		return err
	}
	defer m.Close()
	tok, err := llm.LoadTokenizer(m.Set)
	if err != nil {
		return err
	}

	// The text. A corpus file keeps the context on-distribution; -prompt is
	// the short-input arm, and in free-running mode it is all that is read.
	var ids []int32
	if o.prompt != "" {
		if ids, err = tok.Encode(o.prompt); err != nil {
			return err
		}
	} else {
		buf, err := os.ReadFile(o.file)
		if err != nil {
			return err
		}
		if ids, err = tok.Encode(string(buf)); err != nil {
			return err
		}
	}
	// One extra token, because the last comparison needs the trunk's argmax
	// one step past the last draft.
	want := o.n + o.depth + 2
	if len(ids) < want {
		if !o.free {
			return fmt.Errorf("the text tokenizes to %d tokens, this run needs %d", len(ids), want)
		}
	} else {
		ids = ids[:want]
	}

	draft, err := llm.Open(o.draft)
	if err != nil {
		return fmt.Errorf("draft head: %w", err)
	}
	defer draft.Close()

	dev, done, err := openDevice()
	if err != nil {
		return err
	}
	defer done()

	ctx := o.ctx
	if want := o.n + o.depth + 4; ctx < want {
		ctx = want
	}
	fmt.Printf("%s\n  + %s\n", o.model, o.draft)
	fmt.Printf("%d trunk layers, draft blk.%d, %d cells of context, %d steps, depth %d, %s\n",
		m.Config.NLayer, llm.MTPLayer(m.Config), ctx, o.n, o.depth,
		map[bool]string{true: "free-running", false: "teacher-forced"}[o.free])
	if o.control {
		fmt.Printf("  NEGATIVE CONTROL: the draft is handed a zeroed trunk residual\n")
	}

	start := time.Now()
	g, err := llm.NewGraph(dev, m, llm.GraphOpts{MaxTokens: 1, NKV: ctx, Layers: o.layers})
	if err != nil {
		return err
	}
	defer g.Destroy()
	fmt.Printf("trunk staged in %v\n", time.Since(start).Round(time.Millisecond))

	start = time.Now()
	d, err := llm.NewMTPHead(dev, draft, m.Config, g.Head(), 1, ctx)
	if err != nil {
		return err
	}
	defer d.Destroy()
	fmt.Printf("draft staged in %v: %.2f GB of weights, %.2f GB of arenas (the lm head is the trunk's)\n",
		time.Since(start).Round(time.Millisecond),
		float64(d.WeightBytes())/1e9, float64(d.ActivationBytes())/1e9)

	if err := g.Reset(); err != nil {
		return err
	}
	d.Reset()

	// A guess made at step i is the draft's chain for positions i+2, i+3, …
	// The comparison it is settled against is `greedy[i+1+k]` — the trunk's
	// own argmax from position i+1+k, which is its answer for position
	// i+2+k — and it is not available until the trunk has walked that far.
	// So the walk only records, and the counting is one pass at the end:
	// there is no bookkeeping to get wrong, and the same rows can be
	// re-counted under a different rule without re-running the model.
	type guess struct {
		pos  int     // the position the first entry names
		want []int32 // the chain, oldest first
	}
	var guesses []guess

	zero := make([]float32, m.Config.HC*m.Config.NEmbd)
	var greedy []int32 // greedy[j] is the trunk's argmax from position j

	begin := time.Now()
	var draftTime time.Duration
	cur := ids[0]
	for i := 0; i < o.n+o.depth+1; i++ {
		logits, _, err := g.Extend([]int32{cur})
		if err != nil {
			return fmt.Errorf("trunk step %d: %w", i, err)
		}
		next := llm.Argmax(logits)
		greedy = append(greedy, next)

		// The token the sequence advances on, which is also the token the
		// draft is handed.
		adv := next
		if !o.free && i+1 < len(ids) {
			adv = ids[i+1]
		}

		// The draft chain: the trunk's residual once, then its own.
		if i < o.n {
			h := g.Residual()
			if o.control {
				h = zero
			}
			t0 := time.Now()
			ch, err := d.Chain(h, m, adv, i+1, o.depth)
			draftTime += time.Since(t0)
			if err != nil {
				return fmt.Errorf("draft step %d: %w", i, err)
			}
			guesses = append(guesses, guess{pos: i + 2, want: ch})
		}
		cur = adv
		if (i+1)%32 == 0 {
			fmt.Printf("  %d/%d steps\r", i+1, o.n+o.depth+1)
		}
	}
	wall := time.Since(begin)

	// hit[k] is the draft's k-th guess agreeing with the trunk over every
	// round that reached that far; chain[k] is the same restricted to rounds
	// whose first k guesses were all right, which is the conditional a
	// speculative round actually runs at and the one E[tokens] is built on.
	hit := make([]int, o.depth)
	tried := make([]int, o.depth)
	chainHit := make([]int, o.depth)
	chainTried := make([]int, o.depth)
	for _, p := range guesses {
		alive := true
		for k, w := range p.want {
			// greedy[j] answers for position j+1, so position p.pos+k is
			// answered by greedy[p.pos+k-1].
			j := p.pos + k - 1
			if j >= len(greedy) {
				break
			}
			good := w == greedy[j]
			tried[k]++
			if good {
				hit[k]++
			}
			if alive {
				chainTried[k]++
				if good {
					chainHit[k]++
				} else {
					alive = false
				}
			}
		}
	}

	fmt.Printf("\n%d trunk steps in %v (%.1f ms each), %d draft steps in %v (%.1f ms each)\n",
		o.n+o.depth+1, wall.Round(time.Millisecond),
		float64(wall.Microseconds())/1000/float64(o.n+o.depth+1),
		d.Steps, draftTime.Round(time.Millisecond),
		float64(draftTime.Microseconds())/1000/float64(max(d.Steps, 1)))

	fmt.Printf("\n  k   marginal a_k        chained a_k        E[tokens] at depth k\n")
	rows := [][]string{{"k", "tried", "hit", "a_k", "chain_tried", "chain_hit", "chain_a_k", "e_tokens"}}
	exp := 1.0
	for k := 0; k < o.depth; k++ {
		var a, ca float64
		if tried[k] > 0 {
			a = float64(hit[k]) / float64(tried[k])
		}
		if chainTried[k] > 0 {
			ca = float64(chainHit[k]) / float64(chainTried[k])
		}
		// E[tokens] a round of depth k+1 emits: 1 + sum of the probabilities
		// that the first j drafts are all right, which is chainTried[j]
		// over the rounds that got that far — taken directly as the measured
		// survival fraction rather than as a power of a_1.
		var surv float64
		if chainTried[0] > 0 {
			surv = float64(chainHit[k]) / float64(chainTried[0])
		}
		exp += surv
		fmt.Printf("%3d   %5d/%5d %6.1f%%   %5d/%5d %6.1f%%   %6.3f\n",
			k+1, hit[k], tried[k], 100*a, chainHit[k], chainTried[k], 100*ca, exp)
		rows = append(rows, []string{
			fmt.Sprint(k + 1), fmt.Sprint(tried[k]), fmt.Sprint(hit[k]), fmt.Sprintf("%.4f", a),
			fmt.Sprint(chainTried[k]), fmt.Sprint(chainHit[k]), fmt.Sprintf("%.4f", ca),
			fmt.Sprintf("%.4f", exp),
		})
	}
	if o.csv != "" {
		if err := writePPL(o.csv, rows); err != nil {
			return err
		}
		fmt.Printf("\nwrote %s\n", o.csv)
	}
	return nil
}

