		if rt.rms > 1e-4 {
			t.Errorf("qkv %s: the indexer's columns are rms %.3e from the GEMM's (%v)", k, rt.rms, rt)
		}
	}
	for _, k := range GEMVKernels() {
		if !GEMVFits(k, c.GateWidth()) {
			continue
		}
		_, gotOut := run(GEMVOff, k)
		r, err := compare(gotOut, refOut)

