	if _, ok := qkBank(b); ok {
		switch {
		case tokens == 1:
			return hcQ4DecodePlan()
		case tokens <= 64:
			return HCDownM1, HCUpM4
		case tokens <= 768:
			return HCDownM1, HCUpM8
		case tokens <= 1536:
			return HCDownM2, HCUpM8
		default:
			return HCDownM4, HCUpM4
